package com.skillpilot.backend.identity;

import java.io.PrintWriter;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.platform.engine.TestExecutionResult;
import org.junit.platform.launcher.TestExecutionListener;
import org.junit.platform.launcher.TestIdentifier;
import org.junit.platform.launcher.core.LauncherDiscoveryRequestBuilder;
import org.junit.platform.launcher.core.LauncherFactory;
import org.junit.platform.launcher.listeners.SummaryGeneratingListener;
import static org.junit.platform.engine.discovery.DiscoverySelectors.selectClass;

public class IdentityOwnerContractJUnit {
    public static void main(String[] args) throws Exception {
        var request = LauncherDiscoveryRequestBuilder.request().selectors(
                selectClass(GoalIdentityServiceTest.class), selectClass(GoalStateProjectionTest.class)).build();
        var summary = new SummaryGeneratingListener();
        var launcher = LauncherFactory.create();
        launcher.registerTestExecutionListeners(summary, new TestExecutionListener() {
            @Override public void executionFinished(TestIdentifier id, TestExecutionResult result) {
                if (id.isTest()) System.out.println(result.getStatus() + " " + id.getDisplayName());
            }
        });
        launcher.execute(request);
        var out = new PrintWriter(System.out, true);
        summary.getSummary().printTo(out);
        summary.getSummary().printFailuresTo(out);
        var result = summary.getSummary();
        if (args.length == 1) Files.writeString(Path.of(args[0]), "{\"found\":" + result.getTestsFoundCount()
                + ",\"started\":" + result.getTestsStartedCount() + ",\"succeeded\":" + result.getTestsSucceededCount()
                + ",\"failed\":" + result.getTestsFailedCount() + ",\"skipped\":" + result.getTestsSkippedCount()
                + ",\"aborted\":" + result.getTestsAbortedCount() + "}\n");
        if (result.getTestsFoundCount() != 43 || result.getTestsSkippedCount() != 0 || result.getTestsAbortedCount() != 0
                || result.getTestsFailedCount() != 0) System.exit(1);
    }
}
